\section{Findings}
\label{sec:findings}
The error follows the closed form in Equation~\eqref{eq:err},
based on the classic results of~\cite{turing1950,shannon1948,knuth1984}.
\begin{equation}
  \label{eq:err}
  \varepsilon = \frac{1}{\sqrt{n}}
\end{equation}
Table~\ref{tab:findings} and Figure~\ref{fig:findings} summarise it.

\begin{table}[h]
  \centering
  \begin{tabular}{lr}
    \toprule
    $n$ & $\varepsilon$ \\
    \midrule
    10 & 0.316 \\
    100 & 0.100 \\
    \bottomrule
  \end{tabular}
  \caption{Error against sample size.}
  \label{tab:findings}
\end{table}

\begin{figure}[h]
  \centering
  \begin{tikzpicture}
    \draw[->] (0,0) -- (4,0) node[right] {$n$};
    \draw[->] (0,0) -- (0,2.5) node[above] {$\varepsilon$};
    \draw[thick, red] (0.2,2.2) .. controls (1.5,0.6) and (2.5,0.3) .. (4,0.1);
  \end{tikzpicture}
  \caption{Error falling off with sample size.}
  \label{fig:findings}
\end{figure}

